        if (!comp) { return; }
        const ok = !!b.fn();
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb7", fn: function () { return String(dma_ListInvstgComDetail.get("dpFromEmpCnt")) + " 명"; } },
        { childId: "a_157", fn: function () { return String(dma_ListInvstgComDetail.get("hpage")); } },
        { childId: "__rb12", fn: function () { return String(dma_ListInvstgComDetail.get("dpFromAcntclsMmdd")) + " 월"; } },
        { childId: "__rb20", fn: function () { return String(dma_ListInvstgComDetail.get("dpFromLgshrhdRto")) + " %"; } },
        { childId: "__rb23", fn: function () { return String(dma_ListInvstgComDetail.get("dpFromListShrs")) + " 주"; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        $c.util.getComponent("dialog-loading").setStyle("display", "none");

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst71023.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name fnPopClose
 * @description fn Pop Close 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnPopClose = function () {
    $c.win.closePopup();
};
